import React from 'react';
import { Project } from '@/types';
import ProjectCard from '@/components/ProjectCard';

interface ProjectsSectionProps {
  projects: Project[];
  onOpenProject: (project: Project) => void;
}

export default function ProjectsSection({ projects, onOpenProject }: ProjectsSectionProps) {
  const hackathonProjects = projects.filter((p) => p.type === 'hackathon');
  const personalProjects = projects.filter((p) => p.type === 'personal');

  return (
    <section id="projects" className="relative min-h-[60vh] flex items-center justify-center px-4 py-8 z-10">
      <div className="max-w-6xl w-full">
        <h2 className="text-4xl md:text-5xl font-bold text-white mb-12 text-center">Projects</h2>

        {/* Hackathon Projects */}
        {hackathonProjects.length > 0 && (
          <div className="mb-8">
            <div className="grid md:grid-cols-2 gap-6 mb-6 auto-rows-fr">
              {hackathonProjects.map((project) => (
                <ProjectCard key={project.id} project={project} onOpen={onOpenProject} />
              ))}
            </div>
          </div>
        )}

        {/* Personal Projects */}
        {personalProjects.length > 0 && (
          <div className="mt-8">
            <div className="grid md:grid-cols-2 gap-6 auto-rows-fr">
              {personalProjects.map((project) => (
                <ProjectCard key={project.id} project={project} onOpen={onOpenProject} />
              ))}
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

